// Find the shortest walking route through a small square-tile map.
// grid-pathfinding: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width, height, start_cell, goal_cell, ...row_major_grid]
// Output: [...path_cell_ids] or [] if unreachable
// Cell ID is y*width+x; zero tiles are walkable. BFS with equal-cost four-neighbor movement.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#include "mechanic.h"
#include <assert.h>
#include <math.h>
// Count how many numbers are in this list.
static inline double port_length(const PortVector *a) { return (double)a->count; }
// Check that a position is a whole number inside the list before using it.
static inline size_t port_index(const PortVector *a, double i) { assert(isfinite(i) && i>=0 && i<(double)a->count && floor(i)==i); return (size_t)i; }
// Read one number at a zero-based position; stop if that position does not exist.
static inline double port_get(const PortVector *a, double i) { return a->values[port_index(a,i)]; }
// Replace a number at an existing position in the list.
static inline void port_put(PortVector *a, double i, double v) { a->values[port_index(a,i)] = v; }
// Add one number to the end of the list.
static inline void port_push(PortVector *a, double v) { assert(a->count<PORT_CAPACITY); a->values[a->count++]=v; }
// Round down to a whole number; minus 0.1 becomes minus 1.
static inline double port_floor_num(double a) { return floor(a); }

// 1. Start on the player tile and put it in a waiting line.
// 2. Check nearby tiles: right, left, down, and up. Skip walls and already checked tiles.
// 3. Remember which tile led to each new tile.
// 4. When the target is found, follow those memories backward and reverse them to get the route.
PortVector game_grid_pathfinding_compute(PortVector data) {
    double w = 0;
    double h = 0;
    double start = 0;
    double goal = 0;
    double n = 0;
    PortVector parent = {0};
    PortVector queue = {0};
    double i = 0;
    double head = 0;
    PortVector reverse = {0};
    double cell = 0;
    PortVector result = {0};
    double x = 0;
    double y = 0;
    double direction = 0;
    double nx = 0;
    double ny = 0;
    double other = 0;
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    start = port_get(&data, 2.0);
    goal = port_get(&data, 3.0);
    n = (w * h);
    if (((w < 1.0) || (h < 1.0) || (start < 0.0) || (goal < 0.0) || (start >= n) || (goal >= n) || (port_length(&data) != (n + 4.0)))) {
        return (PortVector){.values={0}, .count=0};
    }
    if (((port_get(&data, (4.0 + start)) != 0.0) || (port_get(&data, (4.0 + goal)) != 0.0))) {
        return (PortVector){.values={0}, .count=0};
    }
    parent = (PortVector){.values={0}, .count=0};
    queue = (PortVector){.values={start}, .count=1};
    i = 0.0;
    while ((i < n)) {
        port_push(&parent, -(1.0));
        i += 1.0;
    }
    port_put(&parent, start, start);
    head = 0.0;
    while ((head < port_length(&queue))) {
        cell = port_get(&queue, head);
        head += 1.0;
        if ((cell == goal)) {
            break;
        }
        x = (cell - (w * port_floor_num((cell / w))));
        y = port_floor_num((cell / w));
        direction = 0.0;
        while ((direction < 4.0)) {
            nx = x;
            ny = y;
            if ((direction == 0.0)) {
                nx += 1.0;
            }
            if ((direction == 1.0)) {
                nx -= 1.0;
            }
            if ((direction == 2.0)) {
                ny += 1.0;
            }
            if ((direction == 3.0)) {
                ny -= 1.0;
            }
            other = ((ny * w) + nx);
            if (((nx >= 0.0) && (nx < w) && (ny >= 0.0) && (ny < h))) {
                if (((port_get(&parent, other) == -(1.0)) && (port_get(&data, (4.0 + other)) == 0.0))) {
                    port_put(&parent, other, cell);
                    port_push(&queue, other);
                }
            }
            direction += 1.0;
        }
    }
    if ((port_get(&parent, goal) == -(1.0))) {
        return (PortVector){.values={0}, .count=0};
    }
    reverse = (PortVector){.values={0}, .count=0};
    cell = goal;
    while ((cell != start)) {
        port_push(&reverse, cell);
        cell = port_get(&parent, cell);
    }
    port_push(&reverse, start);
    result = (PortVector){.values={0}, .count=0};
    i = (port_length(&reverse) - 1.0);
    while ((i >= 0.0)) {
        port_push(&result, port_get(&reverse, i));
        i -= 1.0;
    }
    return result;
}
